   <el-card><template #header><b>天然气资料</b></template><div class="grid"><el-form-item label="是否使用天然气"><el-switch v-model="form.naturalGasUsed"/></el-form-item><template v-if="form.naturalGasUsed"><el-form-item label="天然气管径"><el-select v-model="form.naturalGasCaliberCode" placeholder="请选择"><el-option v-for="x in dictionaries.NATURAL_GAS_CALIBER" :key="x.itemValue" :label="x.itemLabel" :value="x.itemValue"/></el-select></el-form-item><el-form-item label="自动切断阀位置"><el-select v-model="form.gasShutoffLocationCode" placeholder="请选择"><el-option v-for="x in dictionaries.GAS_SHUTOFF_LOCATION" :key="x.itemValue" :label="x.itemLabel" :value="x.itemValue"/></el-select></el-form-item></template></div></el-card>
