 </div>
</template>
<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage}from'element-plus';import{stallApi}from'@/api/merchant';import{cableSpecificationApi,powerSwitchSpecificationApi,dictionaryApi,type CableSpecification,type PowerSwitchSpecification,type DictionaryItem}from'@/api/system';import{useUserStore}from'@/stores/user';
const defaults={cables:[],airConditioners:[],loadPowerKw:null,meterLocation:'',waterSupply:false,waterMeterCaliber:'',waterMeterLocation:'',drainageAvailable:false,drainagePipeCaliber:'',drainagePipelineNo:'',exhaustDuctAvailable:false,exhaustFanCode:'',freshAirDuctAvailable:false,freshAirUnitCode:'',naturalGasUsed:false,naturalGasCaliberCode:'',gasShutoffLocationCode:'',remark:''};const route=useRoute(),router=useRouter(),user=useUserStore(),loading=ref(false),saving=ref(false),meta=reactive<any>({}),form=reactive<any>({...defaults,cables:[],airConditioners:[]}),cableSpecs=ref<CableSpecification[]>([]),switchSpecs=ref<PowerSwitchSpecification[]>([]),meterLocations=ref<DictionaryItem[]>([]),dictionaries=reactive<Record<string,DictionaryItem[]>>({WATER_METER_CALIBER:[],DRAINAGE_PIPE_CALIBER:[],EXHAUST_FAN:[],FRESH_AIR_UNIT:[],AIR_CONDITIONER_SPEC:[],NATURAL_GAS_CALIBER:[],GAS_SHUTOFF_LOCATION:[]});const canEdit=computed(()=>user.user?.roles?.some(r=>['SUPER_ADMIN','SYSTEM_ADMIN'].includes(r)));
function selectableSpecs(){return cableSpecs.value}function refreshCable(row:any){const s=cableSpecs.value.find(x=>x.id===row.cableSpecificationId);if(s)Object.assign(row,{specCode:s.specCode,cableModel:s.cableModel,specification:s.specification,ratedCurrentA:s.ratedCurrentA,ratedPowerKw:s.ratedPowerKw})}function refreshSwitch(row:any){const s=switchSpecs.value.find(x=>x.id===row.powerSwitchSpecificationId);if(s)Object.assign(row,{switchSpecCode:s.specCode,switchBrand:s.brand,switchModel:s.switchModel,switchPoleCount:s.poleCount,switchRatedCurrentA:s.ratedCurrentA,switchBreakingCapacityKa:s.breakingCapacityKa,switchType:s.switchType})}function switchWarning(row:any){return row.powerSwitchSpecificationId&&Number(row.switchRatedCurrentA)>Number(row.ratedCurrentA)?'开关额定电流超过电缆载流量':''}function addCable(){if(!form.cables)form.cables=[];form.cables.push({cableSpecificationId:null,ratedCurrentA:0,ratedPowerKw:0,powerSwitchSpecificationId:null,meterLocationCode:''})}const totalCableQuantity=computed(()=>(form.cables||[]).length);const totalCableCurrent=computed(()=>(form.cables||[]).reduce((n:number,c:any)=>n+(Number(c.ratedCurrentA)||0),0).toFixed(2));const totalCablePower=computed(()=>(form.cables||[]).reduce((n:number,c:any)=>n+(Number(c.ratedPowerKw)||0),0).toFixed(2));
async function load(){loading.value=true;try{const types=Object.keys(dictionaries);const [r,s,sw,locations,...dictRows]:any=await Promise.all([stallApi.getEngineering(Number(route.params.id)),cableSpecificationApi.list(false),powerSwitchSpecificationApi.list(false),dictionaryApi.list('METER_LOCATION',false),...types.map(t=>dictionaryApi.list(t as any,false))]);cableSpecs.value=s;switchSpecs.value=sw;meterLocations.value=locations;types.forEach((t,i)=>dictionaries[t]=dictRows[i]);Object.assign(meta,r);Object.assign(form,defaults,r.profile||{}, {cables:(r.cables||[]).map((x:any)=>({...x})),airConditioners:(r.airConditioners||[]).map((x:any)=>({...x}))})}finally{loading.value=false}}async function save(){if((form.cables||[]).some((x:any)=>!x.cableSpecificationId)){ElMessage.warning('请选择完整的电缆型号规格');return}if((form.cables||[]).some((x:any)=>!x.powerSwitchSpecificationId)){ElMessage.warning('每套供配电回路都需要选择供电端开关');return}if((form.cables||[]).some((x:any)=>!x.meterLocationCode)){ElMessage.warning('每套供配电回路都需要选择电表位置');return}if((form.airConditioners||[]).some((x:any)=>!x.equipmentSpecCode)){ElMessage.warning('请选择完整的空调设备规格');return}saving.value=true;try{await stallApi.saveEngineering(Number(route.params.id),form);ElMessage.success('铺位工程资料已保存');await load()}finally{saving.value=false}}onMounted(load)
</script>
<style scoped>.subtitle{color:#909399;font-size:13px;margin-top:5px}.notice{margin-bottom:14px}.el-card{margin-bottom:14px}.card-title{display:flex;align-items:center;justify-content:space-between}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 16px}.grid .wide{grid-column:span 2}.grid :deep(.el-input-number),.grid :deep(.el-select),.grid :deep(.el-date-editor){width:100%}.cable-row{display:grid;grid-template-columns:minmax(220px,2fr) minmax(145px,1fr) minmax(220px,2fr) minmax(145px,1fr) minmax(180px,1.4fr) 55px;gap:12px;align-items:center;padding:14px 8px;border-bottom:1px solid #ebeef5}.cable-row .el-form-item{margin:0}.cable-row :deep(.el-select){width:100%}.cable-param,.switch-param{display:flex;flex-direction:column;color:#606266;font-size:13px;gap:4px;align-items:flex-start}.equipment-row{display:grid;grid-template-columns:minmax(240px,1fr) 60px;gap:12px;align-items:end;max-width:620px;border-bottom:1px solid #ebeef5;padding:8px}.equipment-row .el-form-item{margin:0}.option-param{float:right;color:#909399;margin-left:20px}.cable-summary{display:flex;justify-content:flex-end;gap:28px;background:#f5f7fa;padding:14px;margin-top:12px}.electric-extra{margin-top:18px}.bottom-save{text-align:center;padding:8px 0 24px}.bottom-save .el-button{min-width:220px}@media(max-width:1200px){.cable-row{grid-template-columns:2fr 1fr 2fr 1fr}.cable-row>button{justify-self:start}}@media(max-width:768px){.page-header{align-items:flex-start}.grid{grid-template-columns:1fr}.grid .wide{grid-column:auto}.el-card{border-radius:10px}.cable-row,.equipment-row{grid-template-columns:1fr;padding:14px 0}.cable-summary{flex-direction:column;gap:8px}.option-param{display:none}}</style>
